insert into public.chapters (id, track_id, subject_id, title, order_index, status) values ('a9867202-3ca2-54a2-9941-de392aef4d4f', '0f9b4ce4-cb41-5347-9ea7-8658e76e77c7', '76af4c0c-14e5-5868-9162-cf037ff3966c', '{"en":"Speed, velocity and acceleration","fr":"Vitesse et accélération"}'::jsonb, 1, 'published')
  on conflict (id) do update set title = excluded.title, order_index = excluded.order_index, status = excluded.status;
insert into public.lessons (id, chapter_id, title, body, estimated_minutes, order_index, status) values ('2cae5e02-6fdb-5f8e-8079-116e433182db', 'a9867202-3ca2-54a2-9941-de392aef4d4f', '{"en":"Describing motion","fr":"Décrire un mouvement"}'::jsonb, '{"en":"# Describing motion\n\n## Speed and velocity\n\n- **Speed** = distance ÷ time (a scalar, unit m/s).\n- **Velocity** is speed in a given direction (a vector).\n\n## Acceleration\n\nAcceleration is the rate of change of velocity:\n\n**a = (v − u) / t**, measured in **m/s²**.\n\n## Equations of uniformly accelerated motion\n\n- v = u + at\n- s = ut + ½at²\n- v² = u² + 2as\n\nwhere u is the initial velocity, v the final velocity, s the displacement and t the time.\n\n## Worked example\n\nA cyclist starts from rest and accelerates at 2 m/s² for 3 s.\nDistance: s = 0 × 3 + ½ × 2 × 3² = **9 m**.","fr":"# Décrire un mouvement\n\n## Vitesse\n\n- **Vitesse moyenne** = distance ÷ durée (en m/s).\n- Le **vecteur vitesse** possède en plus une direction et un sens.\n\n## Accélération\n\n**a = (v − u) / t**, en **m/s²**.\n\n## Mouvement uniformément accéléré\n\n- v = u + at\n- s = ut + ½at²\n- v² = u² + 2as\n\n## Exemple\n\nUn cycliste part du repos avec a = 2 m/s² pendant 3 s : s = ½ × 2 × 3² = **9 m**."}'::jsonb, 10, 0, 'published')
  on conflict (id) do update set title = excluded.title, body = excluded.body, estimated_minutes = excluded.estimated_minutes, order_index = excluded.order_index, status = excluded.status;
