insert into public.lessons (id, chapter_id, title, body, estimated_minutes, order_index, status) values ('4b192392-3fca-5290-b5f2-eccab515ba1b', '89f4811c-144a-5d66-b732-083ce2985b25', '{"fr":"Monohybridisme","en":"Monohybrid crosses"}'::jsonb, '{"fr":"# Monohybridisme\n\n- Un **gène** existe sous plusieurs formes : les **allèles**.\n- **Homozygote** : deux allèles identiques (AA ou aa). **Hétérozygote** : deux allèles différents (Aa).\n- Un allèle **dominant** (A) s''exprime même en un seul exemplaire ; un allèle **récessif** (a) seulement chez aa.\n\n## Première loi : uniformité de la F1\n\nLe croisement de deux lignées pures différant par un caractère donne une F1 **uniforme** (tous Aa).\n\n## Deuxième loi : ségrégation\n\nF1 × F1 (Aa × Aa) donne en F2 : ¼ AA, ½ Aa, ¼ aa, soit **3/4 phénotype dominant et 1/4 récessif**.","en":"# Monohybrid crosses\n\n- **Homozygous**: two identical alleles; **heterozygous**: two different alleles.\n- Crossing two pure lines gives a **uniform F1** (all Aa).\n- Aa × Aa gives **3 dominant : 1 recessive** phenotypes in F2."}'::jsonb, 12, 0, 'published')
  on conflict (id) do update set title = excluded.title, body = excluded.body, estimated_minutes = excluded.estimated_minutes, order_index = excluded.order_index, status = excluded.status;
